-- Executable SQLite relational contract. Not an installed service or PostgreSQL migration.
PRAGMA foreign_keys = ON;
CREATE TABLE tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE users (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), role TEXT NOT NULL CHECK(role IN ('adult','author','reviewer','administrator')), external_subject TEXT UNIQUE, UNIQUE(id,tenant_id));
CREATE TABLE languages (tag TEXT PRIMARY KEY, script TEXT NOT NULL, direction TEXT NOT NULL CHECK(direction IN ('ltr','rtl')), config_json TEXT NOT NULL CHECK(json_valid(config_json)));
CREATE TABLE learners (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), owner_user_id TEXT REFERENCES users(id), age_band TEXT NOT NULL CHECK(age_band IN ('4-8','9-12','13-18','adult','unspecified')), presentation TEXT NOT NULL CHECK(presentation IN ('child','teen','adult')), storage_consent INTEGER NOT NULL DEFAULT 0 CHECK(storage_consent IN (0,1)), UNIQUE(id,tenant_id));
CREATE TABLE parents (id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE REFERENCES users(id));
CREATE TABLE teachers (id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE REFERENCES users(id));
CREATE TABLE guardian_links (parent_id TEXT REFERENCES parents(id), learner_id TEXT REFERENCES learners(id), status TEXT NOT NULL CHECK(status IN ('pending','verified','revoked')), scopes_json TEXT NOT NULL CHECK(json_valid(scopes_json)), PRIMARY KEY(parent_id,learner_id));
CREATE TABLE classes (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), teacher_id TEXT NOT NULL REFERENCES teachers(id), title TEXT NOT NULL);
CREATE TABLE enrolments (class_id TEXT REFERENCES classes(id), learner_id TEXT REFERENCES learners(id), status TEXT NOT NULL CHECK(status IN ('pending','active','revoked')), PRIMARY KEY(class_id,learner_id));
CREATE TABLE consents (id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES learners(id), actor_user_id TEXT REFERENCES users(id), purpose TEXT NOT NULL, policy_version TEXT NOT NULL, granted_at INTEGER NOT NULL, revoked_at INTEGER);
CREATE TABLE content (id TEXT PRIMARY KEY, language_tag TEXT NOT NULL REFERENCES languages(tag), stable_key TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('word','phrase','sentence','form','grammar','story','dialogue','lesson','audio','image','video','assessment','culture')), UNIQUE(language_tag,stable_key));
CREATE TABLE content_versions (id TEXT PRIMARY KEY, content_id TEXT NOT NULL REFERENCES content(id), revision INTEGER NOT NULL CHECK(revision>0), status TEXT NOT NULL CHECK(status IN ('draft','submitted','changes_requested','approved','revoked')), author_id TEXT REFERENCES users(id), payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), sha256 TEXT NOT NULL CHECK(length(sha256)=64), created_at INTEGER NOT NULL, UNIQUE(content_id,revision));
CREATE TABLE sources (id TEXT PRIMARY KEY, title TEXT NOT NULL, locator TEXT NOT NULL, rights TEXT NOT NULL, attribution TEXT NOT NULL);
CREATE TABLE content_sources (version_id TEXT REFERENCES content_versions(id), source_id TEXT REFERENCES sources(id), locator TEXT NOT NULL, PRIMARY KEY(version_id,source_id));
CREATE TABLE reviewers (id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE REFERENCES users(id), languages_json TEXT NOT NULL CHECK(json_valid(languages_json)), scopes_json TEXT NOT NULL CHECK(json_valid(scopes_json)), qualification_evidence TEXT NOT NULL);
CREATE TABLE approvals (id TEXT PRIMARY KEY, version_id TEXT NOT NULL REFERENCES content_versions(id), reviewer_id TEXT NOT NULL REFERENCES reviewers(id), scope TEXT NOT NULL CHECK(scope IN ('language','teaching','rights','accessibility','audio','culture','strokes')), decision TEXT NOT NULL CHECK(decision IN ('approved','changes_requested','revoked')), payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64), notes TEXT NOT NULL, decided_at INTEGER NOT NULL);
CREATE TRIGGER prevent_self_approval BEFORE INSERT ON approvals WHEN NEW.decision='approved' AND (SELECT author_id FROM content_versions WHERE id=NEW.version_id)=(SELECT user_id FROM reviewers WHERE id=NEW.reviewer_id) BEGIN SELECT RAISE(ABORT,'Author cannot approve own version'); END;
CREATE TRIGGER approval_hash_match BEFORE INSERT ON approvals WHEN NEW.payload_hash<>(SELECT sha256 FROM content_versions WHERE id=NEW.version_id) BEGIN SELECT RAISE(ABORT,'Stale approval hash'); END;
CREATE TABLE words (version_id TEXT PRIMARY KEY REFERENCES content_versions(id), script TEXT NOT NULL, sense_key TEXT NOT NULL, meaning TEXT NOT NULL, lexeme_key TEXT NOT NULL, variety TEXT, register_label TEXT);
CREATE TABLE phrases (version_id TEXT PRIMARY KEY REFERENCES content_versions(id), script TEXT NOT NULL, function_key TEXT NOT NULL, meaning TEXT NOT NULL, register_label TEXT);
CREATE TABLE sentences (version_id TEXT PRIMARY KEY REFERENCES content_versions(id), script TEXT NOT NULL, meaning TEXT NOT NULL, context TEXT NOT NULL);
CREATE TABLE forms (version_id TEXT PRIMARY KEY REFERENCES content_versions(id), script TEXT NOT NULL, family_key TEXT NOT NULL, vowel_order INTEGER, CHECK(vowel_order IS NULL OR vowel_order BETWEEN 1 AND 20));
CREATE TABLE grammar_patterns (version_id TEXT PRIMARY KEY REFERENCES content_versions(id), function_key TEXT NOT NULL, explanation TEXT NOT NULL);
CREATE TABLE stories (version_id TEXT PRIMARY KEY REFERENCES content_versions(id), genre TEXT NOT NULL, stage TEXT NOT NULL, segment_json TEXT NOT NULL CHECK(json_valid(segment_json)));
CREATE TABLE dialogues (version_id TEXT PRIMARY KEY REFERENCES content_versions(id), purpose TEXT NOT NULL, roles_json TEXT NOT NULL CHECK(json_valid(roles_json)), turns_json TEXT NOT NULL CHECK(json_valid(turns_json)));
CREATE TABLE lessons (version_id TEXT PRIMARY KEY REFERENCES content_versions(id), objective_id TEXT NOT NULL, sequence_json TEXT NOT NULL CHECK(json_valid(sequence_json)), estimated_minutes INTEGER NOT NULL CHECK(estimated_minutes>0));
CREATE TABLE audio (version_id TEXT PRIMARY KEY REFERENCES content_versions(id), path TEXT NOT NULL, transcript_version_id TEXT REFERENCES content_versions(id), speaker_key TEXT NOT NULL, variety TEXT NOT NULL, duration_ms INTEGER NOT NULL CHECK(duration_ms>0), rights_source_id TEXT NOT NULL REFERENCES sources(id));
CREATE TABLE images (version_id TEXT PRIMARY KEY REFERENCES content_versions(id), path TEXT NOT NULL, alt_text TEXT NOT NULL, rights_source_id TEXT NOT NULL REFERENCES sources(id));
CREATE TABLE videos (version_id TEXT PRIMARY KEY REFERENCES content_versions(id), path TEXT NOT NULL, captions_path TEXT NOT NULL, audio_description_path TEXT, duration_ms INTEGER NOT NULL CHECK(duration_ms>0), rights_source_id TEXT NOT NULL REFERENCES sources(id));
CREATE TABLE content_links (from_version_id TEXT REFERENCES content_versions(id), to_version_id TEXT REFERENCES content_versions(id), relation TEXT NOT NULL CHECK(relation IN ('teaches','recycles','models','illustrates','assesses','audio','requires','variant')), PRIMARY KEY(from_version_id,to_version_id,relation), CHECK(from_version_id<>to_version_id));
CREATE TABLE curriculum_nodes (id TEXT PRIMARY KEY, parent_id TEXT REFERENCES curriculum_nodes(id), language_tag TEXT NOT NULL REFERENCES languages(tag), kind TEXT NOT NULL CHECK(kind IN ('course','stage','unit','module','lesson')), title TEXT NOT NULL, order_index INTEGER NOT NULL CHECK(order_index>=0), content_version_id TEXT REFERENCES content_versions(id));
CREATE TABLE dependencies (node_id TEXT REFERENCES curriculum_nodes(id), prerequisite_id TEXT REFERENCES curriculum_nodes(id), skill TEXT NOT NULL, PRIMARY KEY(node_id,prerequisite_id,skill), CHECK(node_id<>prerequisite_id));
CREATE TABLE assessments (version_id TEXT PRIMARY KEY REFERENCES content_versions(id), objective_id TEXT NOT NULL, skill TEXT NOT NULL, rubric_json TEXT NOT NULL CHECK(json_valid(rubric_json)), accepted_json TEXT NOT NULL CHECK(json_valid(accepted_json)), parallel_set TEXT NOT NULL);
CREATE TABLE attempts (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), learner_id TEXT NOT NULL, target_version_id TEXT NOT NULL REFERENCES content_versions(id), assessment_version_id TEXT REFERENCES assessments(version_id), skill TEXT NOT NULL, session_id TEXT NOT NULL, outcome TEXT NOT NULL CHECK(outcome IN ('correct','incorrect','supported','skipped','exposure')), support_json TEXT NOT NULL CHECK(json_valid(support_json)), model_first INTEGER NOT NULL CHECK(model_first IN (0,1)), occurred_at INTEGER NOT NULL, rubric_score REAL CHECK(rubric_score BETWEEN 0 AND 4), assessor_key TEXT, FOREIGN KEY(learner_id,tenant_id) REFERENCES learners(id,tenant_id));
CREATE TABLE review_states (tenant_id TEXT NOT NULL, learner_id TEXT NOT NULL, target_version_id TEXT NOT NULL REFERENCES content_versions(id), skill TEXT NOT NULL, task_kind TEXT NOT NULL, due_at INTEGER NOT NULL, step INTEGER NOT NULL CHECK(step BETWEEN 0 AND 5), state_json TEXT NOT NULL CHECK(json_valid(state_json)), scheduler_version INTEGER NOT NULL, PRIMARY KEY(learner_id,target_version_id,skill,task_kind), FOREIGN KEY(learner_id,tenant_id) REFERENCES learners(id,tenant_id));
CREATE TABLE progress (learner_id TEXT REFERENCES learners(id), objective_id TEXT NOT NULL, skill TEXT NOT NULL, evidence_json TEXT NOT NULL CHECK(json_valid(evidence_json)), policy_version TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('introduced','practising','demonstrated','needs_review','not_assessed')), PRIMARY KEY(learner_id,objective_id,skill));
CREATE TABLE achievements (id TEXT PRIMARY KEY, objective_id TEXT NOT NULL, rule_json TEXT NOT NULL CHECK(json_valid(rule_json)));
CREATE TABLE learner_achievements (learner_id TEXT REFERENCES learners(id), achievement_id TEXT REFERENCES achievements(id), evidence_json TEXT NOT NULL CHECK(json_valid(evidence_json)), earned_at INTEGER NOT NULL, PRIMARY KEY(learner_id,achievement_id));
CREATE TABLE collections (id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES learners(id), title TEXT NOT NULL);
CREATE TABLE collection_items (collection_id TEXT REFERENCES collections(id), content_version_id TEXT REFERENCES content_versions(id), PRIMARY KEY(collection_id,content_version_id));
CREATE TABLE subscriptions (id TEXT PRIMARY KEY, adult_user_id TEXT NOT NULL REFERENCES users(id), external_customer_key TEXT, status TEXT NOT NULL CHECK(status IN ('inactive','active','cancelled')), entitlements_json TEXT NOT NULL CHECK(json_valid(entitlements_json)));
CREATE TABLE ai_interactions (id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES learners(id), purpose TEXT NOT NULL, model_policy_version TEXT NOT NULL, content_refs_json TEXT NOT NULL CHECK(json_valid(content_refs_json)), outcome TEXT NOT NULL CHECK(outcome IN ('completed','abstained','failed')), occurred_at INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE releases (id TEXT PRIMARY KEY, language_tag TEXT NOT NULL REFERENCES languages(tag), status TEXT NOT NULL CHECK(status IN ('candidate','published','revoked')), policy_version TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE release_items (release_id TEXT REFERENCES releases(id), content_version_id TEXT REFERENCES content_versions(id), PRIMARY KEY(release_id,content_version_id));
CREATE TRIGGER release_approved_only BEFORE INSERT ON release_items WHEN (SELECT status FROM content_versions WHERE id=NEW.content_version_id)<>'approved' BEGIN SELECT RAISE(ABORT,'Unapproved content cannot enter a release'); END;
CREATE TABLE audit_records (id TEXT PRIMARY KEY, actor_user_id TEXT REFERENCES users(id), action TEXT NOT NULL, subject_key TEXT NOT NULL, occurred_at INTEGER NOT NULL, metadata_json TEXT NOT NULL CHECK(json_valid(metadata_json)));
CREATE INDEX review_due ON review_states(tenant_id,learner_id,due_at);
CREATE INDEX attempts_timeline ON attempts(tenant_id,learner_id,occurred_at);
CREATE INDEX content_search ON content(language_tag,stable_key);
CREATE INDEX approval_queue ON approvals(version_id,scope,decision);
CREATE INDEX class_roster ON enrolments(class_id,status,learner_id);
CREATE INDEX versions_status ON content_versions(status,created_at);

CREATE TRIGGER immutable_version_payload BEFORE UPDATE OF content_id,revision,author_id,payload_json,sha256 ON content_versions WHEN NEW.content_id<>OLD.content_id OR NEW.revision<>OLD.revision OR NEW.author_id IS NOT OLD.author_id OR NEW.payload_json<>OLD.payload_json OR NEW.sha256<>OLD.sha256 BEGIN SELECT RAISE(ABORT,'Create a new immutable content version'); END;
CREATE TRIGGER words_kind BEFORE INSERT ON words WHEN (SELECT kind FROM content JOIN content_versions ON content.id=content_versions.content_id WHERE content_versions.id=NEW.version_id)<>'word' BEGIN SELECT RAISE(ABORT,'Wrong content kind for words'); END;
CREATE TRIGGER phrases_kind BEFORE INSERT ON phrases WHEN (SELECT kind FROM content JOIN content_versions ON content.id=content_versions.content_id WHERE content_versions.id=NEW.version_id)<>'phrase' BEGIN SELECT RAISE(ABORT,'Wrong content kind for phrases'); END;
CREATE TRIGGER sentences_kind BEFORE INSERT ON sentences WHEN (SELECT kind FROM content JOIN content_versions ON content.id=content_versions.content_id WHERE content_versions.id=NEW.version_id)<>'sentence' BEGIN SELECT RAISE(ABORT,'Wrong content kind for sentences'); END;
CREATE TRIGGER forms_kind BEFORE INSERT ON forms WHEN (SELECT kind FROM content JOIN content_versions ON content.id=content_versions.content_id WHERE content_versions.id=NEW.version_id)<>'form' BEGIN SELECT RAISE(ABORT,'Wrong content kind for forms'); END;
CREATE TRIGGER grammar_patterns_kind BEFORE INSERT ON grammar_patterns WHEN (SELECT kind FROM content JOIN content_versions ON content.id=content_versions.content_id WHERE content_versions.id=NEW.version_id)<>'grammar' BEGIN SELECT RAISE(ABORT,'Wrong content kind for grammar_patterns'); END;
CREATE TRIGGER stories_kind BEFORE INSERT ON stories WHEN (SELECT kind FROM content JOIN content_versions ON content.id=content_versions.content_id WHERE content_versions.id=NEW.version_id)<>'story' BEGIN SELECT RAISE(ABORT,'Wrong content kind for stories'); END;
CREATE TRIGGER dialogues_kind BEFORE INSERT ON dialogues WHEN (SELECT kind FROM content JOIN content_versions ON content.id=content_versions.content_id WHERE content_versions.id=NEW.version_id)<>'dialogue' BEGIN SELECT RAISE(ABORT,'Wrong content kind for dialogues'); END;
CREATE TRIGGER lessons_kind BEFORE INSERT ON lessons WHEN (SELECT kind FROM content JOIN content_versions ON content.id=content_versions.content_id WHERE content_versions.id=NEW.version_id)<>'lesson' BEGIN SELECT RAISE(ABORT,'Wrong content kind for lessons'); END;
CREATE TRIGGER audio_kind BEFORE INSERT ON audio WHEN (SELECT kind FROM content JOIN content_versions ON content.id=content_versions.content_id WHERE content_versions.id=NEW.version_id)<>'audio' BEGIN SELECT RAISE(ABORT,'Wrong content kind for audio'); END;
CREATE TRIGGER images_kind BEFORE INSERT ON images WHEN (SELECT kind FROM content JOIN content_versions ON content.id=content_versions.content_id WHERE content_versions.id=NEW.version_id)<>'image' BEGIN SELECT RAISE(ABORT,'Wrong content kind for images'); END;
CREATE TRIGGER videos_kind BEFORE INSERT ON videos WHEN (SELECT kind FROM content JOIN content_versions ON content.id=content_versions.content_id WHERE content_versions.id=NEW.version_id)<>'video' BEGIN SELECT RAISE(ABORT,'Wrong content kind for videos'); END;
CREATE TRIGGER assessments_kind BEFORE INSERT ON assessments WHEN (SELECT kind FROM content JOIN content_versions ON content.id=content_versions.content_id WHERE content_versions.id=NEW.version_id)<>'assessment' BEGIN SELECT RAISE(ABORT,'Wrong content kind for assessments'); END;
